testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mesclarConfig, separarResto } from './solution.mjs';

test('mesclarConfig junta as propriedades dos dois objetos', () => {
  assert.deepEqual(mesclarConfig({ cor: 'azul', som: 'ligado' }, { cor: 'verde' }), { cor: 'verde', som: 'ligado' });
});

test('mesclarConfig devolve objeto novo, não o padrão original', () => {
  const padrao = { cor: 'azul' };
  const resultado = mesclarConfig(padrao, {});
  assert.deepEqual(resultado, { cor: 'azul' });
  assert.notEqual(resultado, padrao);
});

test('separarResto devolve tudo menos o nome', () => {
  assert.deepEqual(separarResto({ nome: 'Ana', idade: 15, cidade: 'São Paulo' }), { idade: 15, cidade: 'São Paulo' });
});

test('separarResto sem outras propriedades devolve objeto vazio', () => {
  assert.deepEqual(separarResto({ nome: 'Ana' }), {});
});

solutionCode:
export function mesclarConfig(padrao, extras) {
  return { ...padrao, ...extras };
}

export function separarResto(usuario) {
  const { nome, ...resto } = usuario;
  return resto;
}
